package com.finguard.dao; import java.sql.*;import java.util.*;
public class AuditLogDAO {public void log(Connection c,String type,Long tx,String account,String message)throws SQLException{try(var s=c.prepareStatement("INSERT INTO audit_logs(event_type,transaction_id,account_id,message) VALUES(?,?,?,?)")){s.setString(1,type);if(tx==null)s.setNull(2,Types.BIGINT);else s.setLong(2,tx);s.setString(3,account);s.setString(4,message);s.executeUpdate();}}public List<String> all(Connection c)throws SQLException{var out=new ArrayList<String>();try(var s=c.prepareStatement("SELECT event_time,event_type,account_id,message FROM audit_logs ORDER BY id DESC LIMIT 200");var r=s.executeQuery()){while(r.next())out.add(r.getTimestamp(1)+" | "+r.getString(2)+" | "+r.getString(3)+" | "+r.getString(4));}return out;}}
